pub fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Assumption: tol > 0 (strictly positive). Still handle defensively.
    if tol <= 0 {
        return false;
    }

    let a16 = a as i16;
    let b16 = b as i16;
    let t16 = tol as i16;

    // Check: diff strictly within (-tol, tol)
    let diff = a16 - b16;
    diff > -t16 && diff < t16
}

pub fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    assert!(!a.is_empty(), "input arrays must have positive length");
    assert_eq!(a.len(), b.len(), "input arrays must have equal length");
    assert!(tol > 0, "tolerance must be strictly positive");

    let mut result = Vec::with_capacity(a.len());
    for (x, y) in a.iter().zip(b.iter()) {
        result.push(is_close_i8(*x, *y, tol));
    }
    result
}

