        assert!(is_close_i8(10, 12, 3));   // |10-12|=2 < 3
        assert!(!is_close_i8(10, 13, 3));  // |10-13|=3 == 3 (strict => false)
        assert!(!is_close_i8(10, 14, 3));  // |10-14|=4 > 3
